mapper.update:
    	UPDATE ADM_USER_ATH
		   SET USE_YN = 'N'
		    , LAST_CHNG_USER_ID = #{lastChngUserId}
			, LAST_CHNG_TMSP = SYSTIMESTAMP
		 WHERE USER_ID = #{userId}

mapper.insert:
MERGE INTO ADM_USER_ATH R1 USING(
SELECT #{item.userId} AS userId , #{item.screnTranId} AS screnTranId , #{item.frstRegiUserId} AS frstRegiUserId , #{item.lastChngUserId} AS lastChngUserId FROM DUAL
) T1 ON (R1.USER_ID = T1.userId AND R1.SCREN_TRAN_ID = T1.screnTranId) WHEN MATCHED THEN UPDATE SET R1.USE_YN = 'Y' , R1.LAST_CHNG_USER_ID = T1.lastChngUserId , R1.LAST_CHNG_TMSP = SYSTIMESTAMP WHERE R1.USE_YN = 'N' WHEN NOT MATCHED THEN INSERT ( USER_ID , SCREN_TRAN_ID , USE_YN , FRST_REGI_USER_ID , FRST_REGI_TMSP ) VALUES ( T1.userId , T1.screnTranId , 'Y' , T1.frstRegiUserId , SYSTIMESTAMP )
